using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
namespace NeonSiege {
 // Opt-in executable QA: launch with -siegeQA. Never runs during normal play.
 public sealed class CombatValidation : MonoBehaviour {
  Bootstrap boot;readonly List<string> results=new List<string>();bool passed=true;
  public void Initialize(Bootstrap owner){boot=owner;StartCoroutine(Run());}
  void Check(bool value,string name){passed&=value;results.Add((value?"PASS ":"FAIL ")+name);}
  Enemy Target(Vector3 point){boot.Enemies.Spawn(EnemyKind.Grunt,1,point);foreach(var e in boot.Enemies.Pool)if(e.gameObject.activeSelf&&Vector3.Distance(e.transform.position,point)<2){e.Agent.isStopped=true;return e;}return null;}
  IEnumerator Press(Gamepad pad,GamepadButton button){InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(button));yield return new WaitForSecondsRealtime(.15f);InputSystem.QueueStateEvent(pad,new GamepadState());yield return new WaitForSecondsRealtime(.15f);}
  IEnumerator Run(){yield return new WaitForSecondsRealtime(1);boot.Player.GodMode=true;boot.Session.StartRun();boot.Waves.Stop();boot.Enemies.Clear();yield return new WaitForSecondsRealtime(.3f);var heroAnimator=boot.Player.Visual.GetComponentInChildren<Animator>();float headHeight=heroAnimator.GetBoneTransform(HumanBodyBones.Head).position.y-boot.Player.transform.position.y;float footHeight=heroAnimator.GetBoneTransform(HumanBodyBones.LeftFoot).position.y-boot.Player.transform.position.y;Check(headHeight>1.5f&&footHeight>-.1f&&footHeight<.4f,$"Humanoid pose stays above floor (head {headHeight:F2}m, foot {footHeight:F2}m)");ScreenCapture.CaptureScreenshot(Path.Combine(Application.dataPath,"../gameplay.png"));
   for(int slot=0;slot<5;slot++){boot.Enemies.Clear();var target=Target(new Vector3(0,0,8));Check(target!=null,"Spawn target for weapon "+slot);if(!target)continue;boot.Weapons.Switch(slot);boot.Player.LookAtPoint(target.transform.position+Vector3.up*1.1f);yield return new WaitForSecondsRealtime(.3f);float hp=target.Health;int ammo=boot.Weapons.Ammo;bool shot=boot.Weapons.TryFire();yield return new WaitForSecondsRealtime(slot==4?2.3f:.1f);Check(shot&&target.Health<hp&&boot.Weapons.Ammo==ammo-1,"Weapon "+slot+" damages target and consumes one round");boot.Weapons.Reload();yield return new WaitForSecondsRealtime(boot.Weapons.Current.ReloadTime+.3f);Check(boot.Weapons.Ammo==boot.Weapons.Current.Magazine,"Weapon "+slot+" reload completes");}
   boot.Enemies.Clear();var front=Target(new Vector3(0,0,8));var back=Target(new Vector3(0,0,12));boot.Weapons.Switch(2);boot.Player.LookAtPoint(front.transform.position+Vector3.up*1.1f);yield return new WaitForSecondsRealtime(.3f);boot.Weapons.TryFire();yield return new WaitForSecondsRealtime(.15f);Check(front.Health<=0&&back.Health<=0,"Sniper pierces two enemies");
   boot.Enemies.Clear();boot.Player.Controller.enabled=false;boot.Player.transform.position=new Vector3(12,0,4);boot.Player.Controller.enabled=true;var covered=Target(new Vector3(12,0,15));boot.Player.LookAtPoint(covered.transform.position+Vector3.up);boot.Weapons.Switch(0);yield return new WaitForSecondsRealtime(.3f);boot.Weapons.TryFire();yield return new WaitForSecondsRealtime(.1f);Check(covered.Health==covered.MaxHealth,"Cover blocks hitscan damage");
   boot.Enemies.Clear();boot.Player.ResetRun();var pad=InputSystem.AddDevice<Gamepad>();Vector3 origin=boot.Player.transform.position;InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=Vector2.up});yield return new WaitForSecondsRealtime(.4f);InputSystem.QueueStateEvent(pad,new GamepadState());Check(Vector3.Distance(origin,boot.Player.transform.position)>1,"Simulated gamepad movement");yield return null;InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));yield return new WaitForSecondsRealtime(.12f);Check(boot.Player.DashReady<.2f,"Simulated gamepad dash");InputSystem.RemoveDevice(pad);
   var inputA=new PlayerInput();inputA.Dash.ApplyBindingOverride(0,"<Keyboard>/f");string bindingJson=inputA.Asset.SaveBindingOverridesAsJson();var inputB=new PlayerInput();inputB.Asset.LoadBindingOverridesFromJson(bindingJson);Check(inputB.Dash.bindings[0].effectivePath=="<Keyboard>/f","Rebinding survives a fresh input instance");inputA.Dispose();inputB.Dispose();var original=SaveStore.Load();var fixture=new SaveData{HighScore=12345,Fov=77,Fps=144};SaveStore.Save(fixture);var loaded=SaveStore.Load();Check(loaded.HighScore==12345&&loaded.Fov==77&&loaded.Fps==144,"JSON disk save/load round trip");SaveStore.Save(original);
   var avatar=ArtLibrary.Load().Operator.GetComponent<Animator>()?.avatar;Check(avatar&&avatar.isValid&&avatar.isHuman,"Valid humanoid operator avatar");Check(boot.Audio.Sfx.outputAudioMixerGroup&&boot.Audio.Music.outputAudioMixerGroup,"Audio mixer groups routed");Check(LightmapSettings.lightmaps.Length>0&&LightmapSettings.lightProbes!=null,"Baked lighting and probes loaded");
   boot.Session.Menu();var menuPad=InputSystem.AddDevice<Gamepad>();yield return Press(menuPad,GamepadButton.South);Check(boot.Session.State==RunState.Playing,"Gamepad submits main-menu Deploy button");yield return Press(menuPad,GamepadButton.Start);Check(boot.Session.State==RunState.Paused,"Gamepad opens pause menu");yield return Press(menuPad,GamepadButton.DpadDown);yield return Press(menuPad,GamepadButton.South);Check(boot.Session.CaptureInput,"Gamepad navigates to Settings");ScreenCapture.CaptureScreenshot(Path.Combine(Application.dataPath,"../settings.png"));yield return new WaitForSecondsRealtime(.3f);InputSystem.RemoveDevice(menuPad);
   var beforeEndScreens=SaveStore.Load();var restartPad=InputSystem.AddDevice<Gamepad>();
   boot.Session.End(false);yield return Press(restartPad,GamepadButton.South);Check(boot.Session.State==RunState.Playing&&boot.Waves.Wave==1&&boot.Session.Kills==0,"Gamepad redeploys from defeat with a fresh run");
   boot.Session.End(true);yield return Press(restartPad,GamepadButton.South);Check(boot.Session.State==RunState.Playing&&boot.Waves.Wave==1&&boot.Player.Health==boot.Player.MaxHealth,"Gamepad redeploys from victory with restored health");
   InputSystem.RemoveDevice(restartPad);SaveStore.Save(beforeEndScreens);boot.Session.Save.HighScore=beforeEndScreens.HighScore;
   boot.Session.Menu();yield return new WaitForSecondsRealtime(.3f);ScreenCapture.CaptureScreenshot(Path.Combine(Application.dataPath,"../menu.png"));yield return new WaitForSecondsRealtime(.5f);Screen.SetResolution(2560,1080,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(1);results.Add($"INFO Ultrawide capture resolution: {Screen.width}x{Screen.height}");ScreenCapture.CaptureScreenshot(Path.Combine(Application.dataPath,"../ultrawide.png"));yield return new WaitForSecondsRealtime(.5f);File.WriteAllLines(Path.Combine(Application.dataPath,"../combat-validation.txt"),results);Debug.Log(passed?"COMBAT_QA_PASS":"COMBAT_QA_FAIL");Application.Quit(passed?0:1);
  }
 }
}

